package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99
var WsYear int64 = 0                              // PIC 99
var WsCount int64 = 0                             // PIC 99
var WsBalEd string                                // PIC ZZ,ZZZ,ZZ9.99 len=13

var SchedRecData SchedRec

var inputLines []string
var inputIdx int

func InputDone() bool {
	return WsEofFlag == "Y"
}

func parseImpliedField(s string, scale int32) decimal.Decimal {
	if strings.TrimSpace(s) == "" {
		return decimal.NewFromInt(0)
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ' ' {
			b.WriteByte('0')
		} else if c >= '0' && c <= '9' {
			b.WriteByte(c)
		} else {
			b.WriteByte('0')
		}
	}
	d, err := decimal.NewFromString(b.String())
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return d.Shift(-scale)
}

func parseYearsField(s string) int64 {
	if strings.TrimSpace(s) == "" {
		return 0
	}
	var v int64 = 0
	t := strings.TrimSpace(s)
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return v
}

func parseSchedRec(line string) SchedRec {
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	acct := line[0:4]
	prinStr := line[4:11]
	rateStr := line[11:15]
	yearsStr := line[15:16]
	return SchedRec{
		ScAcct:  acct,
		ScPrin:  parseImpliedField(prinStr, 2),
		ScRate:  parseImpliedField(rateStr, 2),
		ScYears: parseYearsField(yearsStr),
	}
}

func truncateWsBal(d decimal.Decimal) decimal.Decimal {
	if d.IsZero() {
		return decimal.NewFromInt(0)
	}
	neg := d.Sign() < 0
	ad := d.Abs()
	scaled := ad.Mul(decimal.NewFromInt(100)).Truncate(0)
	modBase := decimal.NewFromInt(10000000000)
	mod := scaled.Mod(modBase)
	res := mod.Shift(-2)
	if neg {
		if !mod.IsZero() {
			res = res.Neg()
		} else {
			res = decimal.NewFromInt(0)
		}
	}
	return res
}

func formatPic99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func formatWsBalEd(v decimal.Decimal) string {
	av := v.Abs()
	scaled := av.Mul(decimal.NewFromInt(100)).Truncate(0)
	si := scaled.IntPart()
	// WsBal is truncated to <1e10, fits int64
	if si < 0 {
		si = 0
	}
	intPart := si / 100
	frac := si % 100
	digits := make([]int, 8)
	tmp := intPart
	for i := 7; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	picTypes := []byte{'Z', 'Z', ',', 'Z', 'Z', 'Z', ',', 'Z', 'Z', '9'}
	outInt := make([]byte, 10)
	suppressed := true
	digitIdx := 0
	for j, p := range picTypes {
		if p == ',' {
			if suppressed {
				outInt[j] = ' '
			} else {
				outInt[j] = ','
			}
		} else if p == 'Z' {
			d := digits[digitIdx]
			digitIdx++
			if suppressed && d == 0 {
				outInt[j] = ' '
			} else {
				outInt[j] = byte('0' + d)
				suppressed = false
			}
		} else { // '9'
			d := digits[digitIdx]
			digitIdx++
			outInt[j] = byte('0' + d)
			suppressed = false
		}
	}
	fracTens := int(frac / 10)
	fracUnits := int(frac % 10)
	var sb strings.Builder
	for _, c := range outInt {
		sb.WriteByte(c)
	}
	sb.WriteByte('.')
	sb.WriteByte(byte('0' + fracTens))
	sb.WriteByte(byte('0' + fracUnits))
	return sb.String()
}

func loadInputFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = nil
			inputIdx = 0
			return
		}
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	if len(data) == 0 {
		inputLines = nil
		inputIdx = 0
		return
	}
	content := string(data)
	parts := strings.Split(content, "\n")
	if strings.HasSuffix(content, "\n") {
		parts = parts[:len(parts)-1]
	}
	for i, p := range parts {
		if len(p) > 0 && p[len(p)-1] == '\r' {
			parts[i] = p[:len(p)-1]
		}
	}
	inputLines = parts
	inputIdx = 0
}

func MainPara() {
	loadInputFile()
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	fmt.Println("SCHEDULES: " + formatPic99(WsCount))
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
	} else {
		line := inputLines[inputIdx]
		inputIdx++
		SchedRecData = parseSchedRec(line)
	}
}

func ProcessPara() {
	WsBal = truncateWsBal(SchedRecData.ScPrin)
	WsYear = 1
	for {
		if WsYear > SchedRecData.ScYears {
			break
		}
		factor := decimal.NewFromInt(1).Add(SchedRecData.ScRate.Shift(-2))
		prod := WsBal.Mul(factor)
		rounded := prod.Round(2)
		WsBal = truncateWsBal(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		fmt.Println(SchedRecData.ScAcct + " Y" + formatPic99(WsYear) + " " + WsBalEd)
		WsYear = (WsYear + 1) % 100
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Println(SchedRecData.ScAcct + " FINAL " + WsBalEd)
	WsCount = (WsCount + 1) % 100
	ReadPara()
}

func main() {
	MainPara()
}
